UP = 'up'
DOWN = 'down'
OUTCOMES = (UP, DOWN)
MIN_SAMPLES = 3
MIN_SAMPLE_GAP = 600
MIN_WINDOW = 3600
MAX_WINDOW = 31 * 24 * 3600
FULL = 10000
_MAX_PATH = 120
_MAX_MARKER = 80

def valid_host(host: str) -> bool:
    h = (host or '').strip().lower()
    if not h or len(h) > 100 or h.startswith('.') or h.endswith('.') or ('..' in h):
        return False
    for ch in h:
        if not ('0' <= ch <= '9' or 'a' <= ch <= 'z' or ch in '-.'):
            return False
    return '.' in h

def valid_path(path: str) -> bool:
    p = (path or '').strip()
    if not p.startswith('/') or len(p) > _MAX_PATH:
        return False
    if '..' in p or '://' in p or '?' in p or ('#' in p) or ('//' in p):
        return False
    for ch in p:
        if ch <= ' ' or ch == '\x7f':
            return False
    return True

def valid_marker(marker: str) -> bool:
    m = (marker or '').strip()
    return bool(m) and len(m) <= _MAX_MARKER and ('\n' not in m) and ('\r' not in m)

def url_for(host: str, path: str) -> str:
    return 'https://' + host.strip().lower() + path.strip()

def classify(status: int, body: str, marker: str) -> dict:
    code = int(status)
    if 200 <= code < 300:
        if marker.strip() in (body or ''):
            return {'outcome': UP, 'note': 'answered with the marker'}
        return {'outcome': DOWN, 'note': 'answered without the marker'}
    return {'outcome': DOWN, 'note': 'answered ' + str(code)}

def unreached() -> dict:
    return {'outcome': DOWN, 'note': 'could not be reached'}

def uptime_bp(up: int, samples: int) -> int:
    if samples <= 0:
        return 0
    return int(up) * FULL // int(samples)

def share(fee: int, up: int, samples: int) -> dict:
    total = int(fee)
    up_n = int(up)
    taken = int(samples)
    if total < 0 or up_n < 0 or taken < 0 or (up_n > taken):
        raise ValueError('an impossible tally')
    if taken < MIN_SAMPLES:
        return {'provider': 0, 'buyer': total, 'billed': False}
    provider = total * up_n // taken
    return {'provider': provider, 'buyer': total - provider, 'billed': True}

def epoch_seconds(stamp: str):
    s = (stamp or '').strip()
    if len(s) < 19 or s[4] != '-' or s[7] != '-' or (s[10] != 'T') or (s[13] != ':') or (s[16] != ':'):
        return None
    for i in (0, 1, 2, 3, 5, 6, 8, 9, 11, 12, 14, 15, 17, 18):
        if not '0' <= s[i] <= '9':
            return None
    year, month, day = (int(s[0:4]), int(s[5:7]), int(s[8:10]))
    hour, minute, second = (int(s[11:13]), int(s[14:16]), int(s[17:19]))
    if not 1 <= month <= 12 or day < 1 or day > _days_in_month(year, month):
        return None
    if hour > 23 or minute > 59 or second > 60:
        return None
    return _days_from_civil(year, month, day) * 86400 + hour * 3600 + minute * 60 + second

def _days_in_month(year: int, month: int) -> int:
    if month == 2:
        leap = year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
        return 29 if leap else 28
    return 30 if month in (4, 6, 9, 11) else 31

def _days_from_civil(year: int, month: int, day: int) -> int:
    y = year - (1 if month <= 2 else 0)
    era = (y if y >= 0 else y - 399) // 400
    year_of_era = y - era * 400
    day_of_year = (153 * (month + (-3 if month > 2 else 9)) + 2) // 5 + day - 1
    day_of_era = year_of_era * 365 + year_of_era // 4 - year_of_era // 100 + day_of_year
    return era * 146097 + day_of_era - 719468
from dataclasses import dataclass
import genlayer as gl
from genlayer.types import *

@gl.storage.allow
@dataclass
class Renewal:
    actor: Address
    note: str
    at: str
    uptime_bp: u256

class Grade(gl.contract.Contract):
    operator: Address
    meter: Address
    plan_id: str
    required_bp: u256
    renewals: gl.storage.DynArray[Renewal]

    def __init__(self, meter: str, plan_id: str, required_bp: int):
        self.operator = gl.message.sender_address
        self.meter = _address(meter)
        key = plan_id.strip().lower()
        if not key:
            raise gl.vm.UserError('name the plan this grade reads')
        self.plan_id = key
        bar = int(required_bp)
        if bar <= 0 or bar > FULL:
            raise gl.vm.UserError(f'required uptime is 1 to {FULL} basis points')
        self.required_bp = bar

    @gl.public.write
    def renew(self, note: str) -> dict:
        tally = gl.contract.get_at(self.meter).view().tally(self.plan_id)
        if str(tally['plan_id']).lower() != self.plan_id:
            raise gl.vm.UserError('that tally is about a different plan')
        if not bool(tally['closed']):
            raise gl.vm.UserError('the window is still open, so this stays shut')
        if not bool(tally['enough']):
            raise gl.vm.UserError('too few samples were taken to grade the window')
        measured = int(str(tally['uptime_bp']))
        if measured < int(self.required_bp):
            raise gl.vm.UserError(f'measured {measured} basis points, below the {int(self.required_bp)} required')
        entry = Renewal(actor=gl.message.sender_address, note=note.strip()[:200], at=_stamp(), uptime_bp=measured)
        self.renewals.append(entry)
        return {'renewed': True, 'by': entry.actor.as_hex, 'uptime_bp': str(measured), 'at': entry.at}

    @gl.public.view
    def standing(self) -> dict:
        tally = gl.contract.get_at(self.meter).view().tally(self.plan_id)
        measured = int(str(tally['uptime_bp']))
        closed = bool(tally['closed'])
        enough = bool(tally['enough'])
        return {'operator': self.operator.as_hex, 'meter': self.meter.as_hex, 'plan_id': self.plan_id, 'required_bp': str(self.required_bp), 'uptime_bp': str(measured), 'samples': str(tally['samples']), 'closed': closed, 'enough': enough, 'open': closed and enough and (measured >= int(self.required_bp))}

    @gl.public.view
    def history(self) -> list:
        return [{'actor': r.actor.as_hex, 'note': r.note, 'at': r.at, 'uptime_bp': str(r.uptime_bp)} for r in self.renewals]

def _stamp() -> str:
    return str(gl.message.raw['datetime'])

def _address(value) -> Address:
    if hasattr(value, 'as_hex'):
        return value
    return Address(str(value).strip())
